// Expiry guard (n6). Tray (n4), metadata and media authorization (n3) and view recording (n5) all call it.
// allowed comes from the current audience epoch, never from a cached tray entry.
const visible=(story,allowed,now)=>allowed&&now<story.expiresAt;

for (const story of scanExpired(now, cursor)) {
 hideMetadata(story.id, story.version);
 for (const key of story.renditionKeys) recordDeletionReceipt(await objectStore.delete(key));
 advanceCursorOnlyAfterRecordingPendingKeys(story.id);
}
// Read-time expiry remains authoritative while deletion or backups lag.

for (const row of inbox.scanExpiryAtMost(now)) {
 inbox.removeIfVersion(row.viewerId, row.storyId, row.sourceVersion);
 markPurgePending(row.storyId);
}
